class Solution {
    int gcd(int a, int b) {
        while (b) { int r = a % b; a = b; b = r; }
        return a;
    }
public:
    int validSubarraySplit(vector<int>& nums) {
        int n = nums.size(), INF = 100000000;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 1; i <= n; ++i)
            for (int j = 0; j < i; ++j)
                if (gcd(nums[j], nums[i - 1]) > 1)
                    dp[i] = min(dp[i], dp[j] + 1);
        return dp[n] == INF ? -1 : dp[n];
    }
};
